import{B,read,C,path,circle,pulse}from'../ten-utils.js';
// Original schematic teaching illustrations. These do not claim anatomical scale.
const ellipse=(g,x,y,rx,ry,color,z=0)=>path(g,Array.from({length:73},(_,i)=>[x+rx*Math.cos(i*Math.PI/36),y+ry*Math.sin(i*Math.PI/36),z]),color,2);
const label=(g,x,y,en,hi)=>g.text(x,y,0,B(en,hi));
function cell(g,index,t){if(index===2){g.box(0,0,0,1.4,.95,.15,C.green);g.box(0,0,.02,1.28,.83,.06,C.green);ellipse(g,.18,-.1,.43,.5,C.blue);label(g,.2,.9,'Central vacuole','केंद्रीय रिक्तिका')}else ellipse(g,0,0,1.25,.8,C.green);if(index!==0){g.sphere(-.4,-.1,0,.24,C.blue,B('Nucleus','केंद्रक'));for(let i=0;i<3;i++)ellipse(g,.2+i*.3,.3,.16,.08,C.gold)}else path(g,[[-.5,0,0],[-.2,-.2,0],[.2,.1,0],[.5,-.1,0]],C.gold,3);for(let i=0;i<10;i++)g.sphere(Math.sin(i*4)*1,Math.cos(i*3)*.55,.05,.035,C.white);if(index===2)for(let i=0;i<3;i++)ellipse(g,.4,(i-1)*.35,.2,.1,C.green);}
function plant(g,t){g.line([0,.95,0],[0,-.7,0],C.green,5);for(let side of[-1,1]){for(let i=0;i<3;i++){let y=.4-i*.4;ellipse(g,side*.4,y,.38,.15,C.green);g.line([0,y+.1,0],[side*.65,y,0],C.green)}for(let i=0;i<3;i++)g.line([0,.95,0],[side*(.2+i*.2),1.25+i*.1,0],C.gold)}g.sphere(0,-.8,0,.15,C.pink)}
function flower(g,index){for(let j=0;j<5;j++){let a=j*Math.PI*2/5+.3;g.line([0,.1,-.1],[.9*Math.cos(a),.9*Math.sin(a),-.1],index===0?C.gold:C.green,5)}for(let i=0;i<5;i++){let a=i*Math.PI*2/5;ellipse(g,.55*Math.cos(a),.55*Math.sin(a),.34,.3,index===1?C.gold:C.pink)}for(let i=0;i<5;i++){let a=i*Math.PI*2/5;g.sphere(.32*Math.cos(a),.32*Math.sin(a),.06,.075,index===2?C.gold:C.blue)}g.line([0,.25,.1],[0,-.45,.1],index===3?C.gold:C.green,4);g.sphere(0,.3,.1,.16,C.green);g.line([0,.75,0],[0,1.3,0],C.green,4)}
function neuron(g,index,t,scene){g.sphere(-.9,0,0,.22,C.blue,B('Cell body','कोशिका काय'));for(let i=0;i<5;i++){let a=i*Math.PI*2/5;g.line([-.9,0,0],[-.9+.6*Math.cos(a),.6*Math.sin(a),0],C.green)}g.line([-.65,0,0],[1.3,0,0],C.gold,3);for(let i=0;i<5;i++)g.box(-.3+i*.3,0,0,.1,.1,.08,C.green);for(let i=0;i<3;i++)g.line([1.3,0,0],[1.7,(i-1)*.3,0],C.green);if(!(scene===0&&index===0))pulse(g,[[-.7,0,0],[1.3,0,0]],t);label(g,.4,.65,'Axon → terminal','अक्षतंतु → सिरा')}
function lung(g,index){g.line([0,-1,0],[0,-.3,0],C.white,5);g.line([0,-.3,0],[-.6,.2,0],C.white,3);g.line([0,-.3,0],[.6,.2,0],C.white,3);let r=index===0?.6:.46;ellipse(g,-.65,.4,r,.75,C.pink);ellipse(g,.65,.4,r,.75,C.pink);path(g,[[-1.3,1.35,0],[0,index===0?1.35:1.05,0],[1.3,1.35,0]],C.gold,4)}
function heart(g,index,t){let pts=[[-.65,-.5,0],[-.65,.4,0],[.65,-.5,0],[.65,.4,0]],names=[B('RA','दायाँ आलिंद'),B('RV','दायाँ निलय'),B('LA','बायाँ आलिंद'),B('LV','बायाँ निलय')];pts.forEach((p,i)=>g.sphere(...p,.3,i===index?C.gold:i<2?C.blue:C.pink,names[i]));g.arrow(pts[0],pts[1],C.blue);g.arrow(pts[2],pts[3],C.pink);g.arrow([-.65,.8,0],[-1.4,.8,0],C.blue);g.arrow([1.4,-.5,0],[.9,-.5,0],C.pink);label(g,0,1.25,'Schematic chambers, not anatomy','सांकेतिक कक्ष, वास्तविक आकृति नहीं')}
function nephron(g,index,t){ellipse(g,-.8,-.6,.35,.28,C.blue);for(let i=0;i<6;i++)g.sphere(-.8+Math.sin(i*2)*.2,-.6+Math.cos(i*2)*.15,0,.05,C.pink);let pts=[[-.5,-.6,0],[0,-.5,0],[-.1,1,0],[.5,1,0],[.6,-.5,0],[1,-.4,0],[1,1.3,0]];path(g,pts,C.green,4);pulse(g,pts,t);label(g,-.8,-1.1,'Renal corpuscle','वृक्क कणिका');label(g,.2,1.6,'Loop of Henle','हेनले लूप')}
function muscle(g,index){let d=index===2?.8:1.25;g.line([-d,-.6,0],[-d,.6,0],C.white,4);g.line([d,-.6,0],[d,.6,0],C.white,4);for(let side of[-1,1])for(let j of[-.32,.32])g.line([side*d,j,0],[side*(d-1),j,0],C.green,4);g.line([-.6,0,0],[.6,0,0],C.pink,8);label(g,0,1,'A band: constant length','A पट्टी: लंबाई स्थिर')}
function chromosomes(g,index,scene){
const rod=(x,y,rep,color)=>{g.line([x-.08,y-.14,0],[x+.08,y+.14,0],color,3);if(rep)g.line([x+.08,y-.14,0],[x-.08,y+.14,0],color,3)};
if(scene===2){let count=index===0?1:index===1?2:4;for(let c=0;c<count;c++){let cx=count===1?0:(c%2-.5)*1.5,cy=count<=2?0:(Math.floor(c/2)-.5)*1.1;ellipse(g,cx,cy,count===1?1.2:.6,count===1?.9:.44,C.green);let nr=index===0?4:2;for(let j=0;j<nr;j++)rod(cx+(j%2-.5)*.4,cy+(Math.floor(j/2)-.5)*.35,index<2,j%2?C.pink:C.blue)}}
else if(scene===0&&index===3||scene===1&&index===3){for(let side of[-1,1]){ellipse(g,side*.75,0,.65,.8,C.green);for(let j=0;j<4;j++)rod(side*.75+(j%2-.5)*.35,(Math.floor(j/2)-.5)*.5,false,j<2?C.blue:C.pink)}}
else{ellipse(g,0,0,1.3,.9,C.green);let nr=scene===1&&index===2?8:4;for(let j=0;j<nr;j++){let x=scene===1&&index===1?0:scene===1&&index===2?(j<4?-.8:.8):(j%2-.5)*.6,y=scene===1&&index===1?(j-1.5)*.35:(j%4-1.5)*.35;let rep=scene===0?index===2||index===1&&j<2: index<2;rod(x,y,rep,j%2?C.pink:C.blue)}}
label(g,0,1.3,'Model cell: 2n=4; stages are snapshots','मॉडल कोशिका: 2n=4; अवस्थाएँ स्थिर झलकियाँ')}
function section(g,index,scene){circle(g,0,0,1,C.green);if(scene!==1){circle(g,0,0,.7,index===0?C.gold:C.green);for(let j=0;j<6;j++){let a=j*Math.PI/3;g.sphere(.55*Math.cos(a),.55*Math.sin(a),0,.09,index===2?C.gold:C.blue)}label(g,0,1.35,'Tissue-system overview, not an organ section','ऊतक तंत्र का परिचय, अंग की वास्तविक काट नहीं');return}
if(index<=1){let n=index===0?4:8;for(let j=0;j<n*2;j++){let a=j*Math.PI/n;g.sphere(.55*Math.cos(a),.55*Math.sin(a),0,.075,j%2?C.pink:C.blue)}circle(g,0,0,index===0?.12:.3,C.green)}else for(let j=0;j<9;j++){let a=j*2.4,r=index===3?.2+(j%3)*.25:.62;g.sphere(r*Math.cos(a),r*Math.sin(a),0,.075,C.blue);g.sphere((r+.12)*Math.cos(a),(r+.12)*Math.sin(a),0,.05,C.pink)}label(g,0,1.35,'Blue xylem / pink phloem; radial vs conjoint','नीला जाइलम / गुलाबी फ्लोएम; अरीय या संयुक्त')}
export default function render({g,t,p,extra,low}){const i=Math.max(0,Math.min(extra.entries.length-1,Math.round(p[0]))),entry=extra.entries[i],kind=extra.diagram;
if(kind==='cell')cell(g,extra.chapter===8&&extra.sceneIndex===0?i:2,t);
else if(kind==='plant')plant(g,t);
else if(kind==='leaf'){if(extra.chapter===6){g.box(0,0,0,1.3,.8,.06,C.green);for(let k=0;k<5;k++)g.box(-1+k*.5,-.35,0,.15,.3,.04,i===1?C.gold:C.green);for(let k=0;k<7;k++)g.sphere(Math.sin(k*3)*1,.35+Math.cos(k*2)*.2,0,.1,i===2?C.gold:C.blue);label(g,0,-1.2,'Upper epidermis / palisade layer','ऊपरी बाह्यत्वचा / खंभ ऊतक');label(g,0,1.35,'Spongy layer / lower stomata','स्पंजी ऊतक / निचले रंध्र')}else{g.box(-.7,0,0,.55,.8,.05,C.green);g.box(.7,0,0,.55,.8,.05,C.blue);g.arrow([-.1,0,0],[.1,0,0],C.gold);label(g,-.7,-1.2,extra.chapter===11&&extra.sceneIndex===2?'Mesophyll':'Thylakoid',extra.chapter===11&&extra.sceneIndex===2?'पर्णमध्योतक':'थाइलेकोइड');label(g,.7,1.3,extra.chapter===11&&extra.sceneIndex===2?'Bundle sheath':'Stroma',extra.chapter===11&&extra.sceneIndex===2?'पूल आच्छद':'स्ट्रोमा')}}
else if(kind==='flower')flower(g,i);
else if(kind==='section')section(g,i,extra.sceneIndex);
else if(kind==='neuron')neuron(g,i,t,extra.sceneIndex);
else if(kind==='lung')lung(g,i);
else if(kind==='heart')heart(g,i,t);
else if(kind==='nephron')nephron(g,i,t);
else if(kind==='muscle')muscle(g,i);
else if(kind==='chromosome')chromosomes(g,i,extra.sceneIndex);
else if(kind==='molecule'){for(let j=0;j<6;j++){let a=j*.7;g.sphere(-1.3+j*.5,.25*Math.sin(a+i),.25*Math.cos(a+i),.12,j%2?C.green:C.blue);if(j)g.line([-1.3+(j-1)*.5,.25*Math.sin(a-.7+i),.25*Math.cos(a-.7+i)],[-1.3+j*.5,.25*Math.sin(a+i),.25*Math.cos(a+i)],C.white,2)}}
else if(kind==='enzyme'){g.sphere(-.4,0,0,.5,C.green,B('Enzyme','एंजाइम'));for(let j=0;j<3+i*4;j++)g.sphere(.3+Math.sin(j*3+t*.2)*.8,Math.cos(j*4+t*.2)*.6,.1,.07,C.gold);label(g,0,1,'Substrate occupancy is symbolic','क्रियाधार व्याप्ति सांकेतिक')}
else if(kind==='blood'){for(let j=0;j<(low?8:16);j++)g.sphere(Math.sin(j*3+t*.15)*1.2,Math.cos(j*4)*.7,Math.sin(j)*.3,j%4?.12:.18,i===2&&j%4===0?C.white:i===3?C.gold:C.pink)}
else if(kind==='frog'){ellipse(g,0,.1,.65,.85,C.green);g.sphere(0,-.8,0,.38,C.green);for(let side of[-1,1]){g.sphere(side*.2,-1,0,.08,C.gold);path(g,[[side*.45,.5,0],[side*1.1,.9,0],[side*.7,1.25,0]],C.green,5);g.line([side*.4,0,0],[side*.9,.45,0],C.green,3)}}
else if(kind==='joint'){g.line([-1,-.3,0],[0,0,0],C.white,9);g.sphere(0,0,0,.2,C.gold);let a=i*Math.PI/6;g.line([0,0,0],[Math.cos(a),Math.sin(a),0],C.white,9)}
else if(kind==='endocrine'){g.sphere(-1,0,0,.25,C.green,B('Hormone source','हार्मोन स्रोत'));g.arrow([-.65,0,0],[.65,0,0],C.gold);g.sphere(1,0,0,.3,C.blue,B('Target / receptor','लक्ष्य / ग्राही'));for(let j=0;j<3;j++)g.sphere(-.5+((t*.3+j*.3)%1),0,0,.05,C.gold);label(g,0,1,'Conceptual signal; not gland locations','सांकेतिक संकेत; ग्रंथियों के स्थान नहीं')}
// Concept/hierarchy/cycle panels intentionally use labelled nodes, not fake anatomical objects.
if(['concept','hierarchy','cycle'].includes(kind)){const count=extra.entries.length;extra.entries.forEach((e,j)=>{let angle=-Math.PI/2+j*Math.PI*2/count,pos=kind==='hierarchy'?[-1.1+(j%2)*2.2,-1.3+Math.floor(j/2)*.85,0]:[1.25*Math.cos(angle),.9*Math.sin(angle),0];g.sphere(...pos,j===i?.15:.08,j===i?C.gold:C.green,e.label);if(kind==='cycle'){let a=-Math.PI/2+((j+1)%count)*Math.PI*2/count;g.arrow(pos,[1.25*Math.cos(a),.9*Math.sin(a),0],C.green)}if(kind==='hierarchy'&&j){let prev=[-1.1+((j-1)%2)*2.2,-1.3+Math.floor((j-1)/2)*.85,0];g.arrow(prev,pos,j<=i?C.gold:C.green)}})}
else g.text(0,-1.65,0,entry.label);
return[read('Selected concept','चुनी अवधारणा',entry.label),read('Stage / choice','अवस्था / चयन',`${i+1} / ${extra.entries.length}`),read('Explanation','व्याख्या',entry.text)]}
